  "test": "import asyncio
import pytest
from unittest import mock

import browser_use.sync.service as sync_mod

@pytest.fixture(autouse=True)
def enable_sync(monkeypatch):
    # Force cloud sync enabled
    monkeypatch.setattr(sync_mod.CONFIG, 'BROWSER_USE_CLOUD_SYNC', True, raising=False)
    # Stub DeviceAuthClient to a simple dummy
    class DummyAuth:
        is_authenticated = False
        def get_headers(self):
            return {}
    monkeypatch.setattr(sync_mod, 'DeviceAuthClient', lambda base_url=None: DummyAuth())

class DummyResponse:
    def __init__(self, status_code, text, url):
        self.status_code = status_code
        self.text = text
        self.request = mock.Mock()
        self.request.url = url

class DummyAsyncClient:
    def __init__(self, *args, **kwargs):
        pass
    async def __aenter__(self):
        return self
    async def __aexit__(self, exc_type, exc, tb):
        return False
    async def post(self, *args, **kwargs):
        return DummyResponse(500, "boom", "http://example.com/api")

class DummyEvent:
    event_type = 'TestEvent'
    def __init__(self):
        self.user_id = None
    def model_dump(self, mode='json'):
        return {'event_type': self.event_type}

@pytest.mark.asyncio
async def test_sync_failure_logs_error(monkeypatch, caplog):
    monkeypatch.setattr(sync_mod, 'httpx', mock.Mock(AsyncClient=DummyAsyncClient))
    cs = sync_mod.CloudSync()
    ev = DummyEvent()
    caplog.set_level('ERROR')
    await cs._send_event(ev)
    # Verify that an error log entry was emitted containing the response text
    errors = [rec for rec in caplog.records if rec.levelname == 'ERROR']
    assert any('Failed to send sync event' in rec.getMessage() and 'boom' in rec.getMessage() for rec in errors)
